class C:
    def puede(self, m):
        return m <= self.saldo

    def __init__(self, s):
        self.saldo = s

    def retirar(self, m):
        if not self.puede(m):
            raise ValueError("no alcanza")
        self.saldo -= m

class Corriente(C):
    def puede(self, m):
        return m <= self.saldo + 100

c = Corriente(50)
c.retirar(120)
print(c.saldo)

